/**
 * A file attached to a prompt, shown as a chip (`design/components/attachment-chip.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/attachment-chip.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import {
  Icon,
  MEMBER_PROVIDERS,
  Ref,
  agentMember,
  elementRef,
  formatBytes,
  mountEffect,
  useMember,
  type IconProps,
  type IconRole,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/ai/attachment-chip.module.css'
import { Button, type ButtonProps } from '../controls/Button'
import { Link, type LinkProps } from '../controls/Link'
import { Spinner, type SpinnerProps } from '../structure/Spinner'

export type AttachmentStatus = 'uploading' | 'done' | 'error'

/** A file attached to a prompt, shown as a chip: the inputs it takes, by the React member's prop names. */
export interface AttachmentChipProps {
  /**
   * The file's URL, which makes the name a link that opens in a new tab (Link's `external`).
   */
  href?: string
  /**
   * The leading mark, `document` by default, or `table` or `browser` when the app knows the
   * kind.
   */
  icon?: IconRole
  /**
   * The app's text for a failure, which the chip never writes itself.
   */
  message?: string
  /**
   * The file's name, ellipsed when the row is narrow.
   */
  name: string
  /**
   * The remove button's accessible name (default `Remove {name}`), which apps pass to localize.
   */
  removeLabel?: string
  /**
   * The size in bytes, formatted by the engine's `formatBytes`, as FileUpload's rows are, so
   * sizes match in both places.
   */
  size?: number
  /**
   * The upload status, where `done` is the rest state.
   */
  status?: 'error' | 'uploading' | 'done'
  /**
   * The status announced while the file uploads (default `{name}: uploading`), which apps pass
   * to localize.
   */
  uploadingLabel?: string
}

/** A file attached to a prompt, shown as a chip. */
@Component({
  selector: 'pm-attachment-chip',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref, Button, Icon, Link, Spinner],
  // prettier-ignore
  template: `<!-- chip -->
<span
[attr.class]="e1()"
[attr.data-status]="e2()"
data-member="attachment-chip"
[pmRef]="chip"
><!-- mark -->
<span
[attr.class]="e3()"
>@if (e4()) {<pm-spinner
size="sm"
[label]="e5()"
></pm-spinner>} @else if (e6()) {<pm-icon
name="error"
size="sm"
></pm-icon>} @else {<pm-icon
[name]="e7()"
size="sm"
></pm-icon>}</span>
<!-- body -->
<span
[attr.class]="e8()"
><!-- name -->
<span
[attr.class]="e9()"
[pmRef]="file"
>@if (e10()) {{{ e11() }}} @else {<pm-link
[href]="e12()"
[external]="e13()"
>{{ e14() }}</pm-link>}</span>
@if (e15()) {<!-- meta -->
<span
[attr.class]="e16()"
>{{ e17() }}</span>}
@if (e18()) {<!-- message -->
<span
[attr.class]="e19()"
>{{ e20() }}</span>}</span>
@if (e21()) {<pm-button
variant="ghost"
tone="neutral"
size="sm"
[iconOnly]="e22()"
icon="close"
[label]="e23()"
(click)="h1()"
></pm-button>}</span>`,
})
export class AttachmentChip {
  /**
   * The file's URL, which makes the name a link that opens in a new tab (Link's `external`).
   */
  readonly href = input<AttachmentChipProps['href']>(undefined)
  /**
   * The leading mark, `document` by default, or `table` or `browser` when the app knows the
   * kind.
   */
  readonly icon = input<
    Exclude<AttachmentChipProps['icon'], undefined>,
    AttachmentChipProps['icon']
  >('document', {
    transform: (value: AttachmentChipProps['icon']) => (value === undefined ? 'document' : value),
  })
  /**
   * The app's text for a failure, which the chip never writes itself.
   */
  readonly message = input<AttachmentChipProps['message']>(undefined)
  /**
   * The file's name, ellipsed when the row is narrow.
   */
  readonly name = input.required<AttachmentChipProps['name']>()
  /**
   * The remove button's accessible name (default `Remove {name}`), which apps pass to localize.
   */
  readonly removeLabel = input<AttachmentChipProps['removeLabel']>(undefined)
  /**
   * The size in bytes, formatted by the engine's `formatBytes`, as FileUpload's rows are, so
   * sizes match in both places.
   */
  readonly size = input<AttachmentChipProps['size']>(undefined)
  /**
   * The upload status, where `done` is the rest state.
   */
  readonly status = input<
    Exclude<AttachmentChipProps['status'], undefined>,
    AttachmentChipProps['status']
  >('done', {
    transform: (value: AttachmentChipProps['status']) => (value === undefined ? 'done' : value),
  })
  /**
   * The status announced while the file uploads (default `{name}: uploading`), which apps pass
   * to localize.
   */
  readonly uploadingLabel = input<AttachmentChipProps['uploadingLabel']>(undefined)
  /**
   * Shows the remove button when supplied, and is omitted in a sent message, where removal is
   * over.
   */
  readonly onRemove = output<void>({ alias: 'remove' })
  protected readonly $ = useMember({
    events: ['remove'],
    props: {
      href: () => this.href(),
      icon: () => this.icon(),
      message: () => this.message(),
      name: () => this.name(),
      removeLabel: () => this.removeLabel(),
      size: () => this.size(),
      status: () => this.status(),
      uploadingLabel: () => this.uploadingLabel(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly chip = elementRef<HTMLElement>()
  protected readonly file = elementRef<HTMLElement>()
  private release1: (() => void) | undefined

  constructor() {
    inject(DestroyRef).onDestroy(() => this.release1?.())
    mountEffect(() => this.effect1())
  }

  protected e1() {
    return styles.chip
  }

  protected e2() {
    return this.$p.status
  }

  protected e3() {
    return styles.mark
  }

  protected e4() {
    return this.$p.status === 'uploading'
  }

  protected e5(): SpinnerProps['label'] {
    if (!(this.$p.status === 'uploading')) return undefined as never
    return this.$p.uploadingLabel ?? `${this.$p.name}: uploading`
  }

  protected e6() {
    if (this.$p.status === 'uploading') return undefined as never
    return this.$p.status === 'error'
  }

  protected e7(): IconProps['name'] {
    if (this.$p.status === 'uploading') return undefined as never
    if (this.$p.status === 'error') return undefined as never
    return this.$p.icon
  }

  protected e8() {
    return styles.body
  }

  protected e9() {
    return styles.name
  }

  protected e10() {
    return this.$p.href === undefined
  }

  protected e11() {
    if (!(this.$p.href === undefined)) return undefined as never
    return this.$p.name
  }

  protected e12(): LinkProps['href'] {
    if (this.$p.href === undefined) return undefined as never
    return this.$p.href
  }

  protected e13(): LinkProps['external'] {
    if (this.$p.href === undefined) return undefined as never
    return true
  }

  protected e14() {
    if (this.$p.href === undefined) return undefined as never
    return this.$p.name
  }

  protected e15() {
    return this.$p.size !== undefined && this.$p.status !== 'error'
  }

  protected e16() {
    if (!(this.$p.size !== undefined && this.$p.status !== 'error')) return undefined as never
    return styles.meta
  }

  protected e17() {
    if (!(this.$p.size !== undefined && this.$p.status !== 'error')) return undefined as never
    return formatBytes(this.$p.size)
  }

  protected e18() {
    return this.$p.status === 'error' && this.$p.message !== undefined
  }

  protected e19() {
    if (!(this.$p.status === 'error' && this.$p.message !== undefined)) return undefined as never
    return styles.message
  }

  protected e20() {
    if (!(this.$p.status === 'error' && this.$p.message !== undefined)) return undefined as never
    return this.$p.message
  }

  protected e21() {
    return this.$.listening(this.onRemove, 'onRemove')
  }

  protected e22(): ButtonProps['iconOnly'] {
    if (!this.$.listening(this.onRemove, 'onRemove')) return undefined as never
    return true
  }

  protected e23(): ButtonProps['label'] {
    if (!this.$.listening(this.onRemove, 'onRemove')) return undefined as never
    return this.$p.removeLabel ?? `Remove ${this.$p.name}`
  }

  protected h1(): void {
    if (!this.$.listening(this.onRemove, 'onRemove')) return
    this.$.emit(this.onRemove, 'onRemove')
  }

  private effect1(): void {
    this.release1?.()
    const ran = agentMember({
      member: 'AttachmentChip',
      element: () => this.file.value,
      state: () => ({ name: this.$p.name, status: this.$p.status }),
      actions: {
        remove: () =>
          (() => {
            if (!this.$.listening(this.onRemove, 'onRemove'))
              throw new Error('The chip records a sent file and has no remove control.')
            this.$.emit(this.onRemove, 'onRemove')
          })(),
      },
      withholds: () => this.chip.value,
    })
    this.release1 = () => {
      ran()
    }
  }
}
